import json
import pathlib
import re
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from kaleidoscope_worker import call_app

request = json.load(sys.stdin)
trigger = request.get('trigger') or {}
storage = request.get('storage') or {}
secrets = request.get('secrets') or {}
state_dir = pathlib.Path(request['state_dir'])
status = dict(storage.get('status') or {})
logs = list(storage.get('logs') or [])
writes = {}
bot_token = secrets.get('slack_bot_token') or ''
api_base = (storage.get('api_base_url') or 'https://slack.com/api').rstrip('/')
now = request.get('now') or ''


class PollRateLimited(Exception):
    def __init__(self, retry_at):
        self.retry_at = retry_at


def slack(method, data=None):
    payload = json.dumps(data or {}, ensure_ascii=False).encode('utf-8')
    req = urllib.request.Request(api_base + '/' + method, data=payload, headers={'Authorization': 'Bearer ' + bot_token, 'Content-Type': 'application/json; charset=utf-8'})
    try:
        with urllib.request.urlopen(req, timeout=15) as response:
            result = json.load(response)
    except urllib.error.HTTPError as error:
        if error.code == 429 and (action == 'poll_now' or kind == 'schedule'):
            try:
                delay = max(0, int(float(error.headers.get('Retry-After') or 60)))
            except (TypeError, ValueError):
                delay = 60
            raise PollRateLimited(int(time.time()) + delay)
        raise
    if not result.get('ok'):
        raise RuntimeError(result.get('error') or '슬랙 요청 실패')
    return result


def check_connection():
    status['last_checked_at'] = now
    if not bot_token:
        status['state'] = '토큰 미설정'
        status['last_error'] = ''
    else:
        try:
            info = slack('auth.test')
            status.update({'state': '연결됨', 'team_name': info.get('team') or '-', 'bot_name': info.get('user') or '-', 'bot_user_id': info.get('user_id') or '', 'last_error': ''})
        except PollRateLimited:
            raise
        except (OSError, ValueError, RuntimeError) as error:
            status.update({'state': '오류', 'last_error': str(error)})
    writes['status'] = status


def read_file(name, default):
    try:
        return json.loads((state_dir / name).read_text(encoding='utf-8'))
    except FileNotFoundError:
        return default


def write_file(name, value):
    (state_dir / name).write_text(json.dumps(value, ensure_ascii=False), encoding='utf-8')


def allowed(channel, explicit=False):
    channels = [part for part in re.split(r'[\s,]+', storage.get('allowed_channels') or '') if part]
    return channel in channels if explicit else not channels or channel in channels


def respond(event, event_id=''):
    channel = event.get('channel') or ''
    user = event.get('user') or ''
    if not allowed(channel) or event.get('bot_id') or event.get('subtype') or (user and user == status.get('bot_user_id')):
        return {'ignored': True}
    event_key = channel + ':' + event['ts'] if channel and event.get('ts') else event_id
    processed = read_file('processed.json', [])
    if event_key in processed:
        return {'duplicate': True}
    text = re.sub(r'<@[A-Z0-9]+>', '', event.get('text') or '').strip()
    if not text:
        return {'ignored': True}
    thread = event.get('thread_ts') or event.get('ts') or ''
    answer = call_app('agent', 'ask', {'prompt': text, 'session_key': 'slack:' + channel + ':' + thread, 'system_prompt': storage.get('system_prompt') or '', 'agent_id': storage.get('agent_id') or ''})
    reply = answer['reply']
    if bot_token:
        message = {'channel': channel, 'text': reply}
        if event.get('thread_ts'):
            message['thread_ts'] = event['thread_ts']
        slack('chat.postMessage', message)
    logs.insert(0, {'id': event_key, 'time': now, 'channel': channel, 'user': user, 'prompt': text, 'reply': reply, 'status': '완료'})
    del logs[50:]
    status['total_replies'] = status.get('total_replies', 0) + 1
    writes.update({'logs': logs, 'status': status})
    processed.append(event_key)
    write_file('processed.json', processed[-1000:])
    return {'reply': reply}


kind = trigger.get('kind')
action = trigger.get('action')
args = trigger.get('args') or {}
result = {}
if kind == 'webhook':
    body = trigger.get('body') or {}
    if body.get('type') == 'url_verification':
        print(json.dumps({'http_response': {'status': 200, 'headers': {'content-type': 'application/json'}, 'body': {'challenge': body.get('challenge', '')}}}, ensure_ascii=False))
    elif body.get('type') == 'event_callback':
        event = body.get('event') or {}
        ignored = event.get('bot_id') or event.get('subtype') or event.get('user') == status.get('bot_user_id') or event.get('type') not in ('app_mention', 'message')
        output = {'http_response': {'status': 200, 'headers': {'content-type': 'application/json'}, 'body': {'ok': True}}}
        if ignored:
            output['http_response']['body']['ignored'] = True
        else:
            output['defer'] = {'action': 'handle_event', 'args': {'event': event, 'event_id': body.get('event_id', '')}}
        print(json.dumps(output, ensure_ascii=False))
    else:
        print(json.dumps({'http_response': {'status': 200, 'body': {'ok': True, 'ignored': True}}}))
    sys.exit(0)
elif action == 'handle_event':
    result = respond(args.get('event') or {}, args.get('event_id') or '')
elif action == 'check_connection' or kind == 'watch':
    check_connection()
elif action == 'clear_logs':
    writes['logs'] = []
elif action == 'send_test':
    prompt = args.get('prompt') or '안녕하세요! 슬랙봇 연결 테스트입니다. 한 줄로 인사해 주세요.'
    answer = call_app('agent', 'ask', {'prompt': prompt, 'session_key': 'slack:test', 'system_prompt': storage.get('system_prompt') or '', 'agent_id': storage.get('agent_id') or ''})
    reply = answer['reply']
    channel = args.get('channel') or storage.get('test_channel') or ''
    if channel and bot_token:
        slack('chat.postMessage', {'channel': channel, 'text': reply})
    logs.insert(0, {'id': 'test:' + str(time.time_ns()), 'time': now, 'channel': channel, 'user': '', 'prompt': prompt, 'reply': reply, 'status': '완료'})
    writes.update({'logs': logs[:50], 'status': status})
    status['total_replies'] = status.get('total_replies', 0) + 1
    result = {'reply': reply}
elif action == 'poll_now' or kind == 'schedule':
    poll_state = read_file('poll_state.json', {})
    if bot_token and time.time() >= float(poll_state.get('retry_at') or 0):
        try:
            if not status.get('bot_user_id'):
                check_connection()
            if status.get('bot_user_id'):
                channels = slack('conversations.list', {'types': 'im,public_channel,private_channel', 'limit': 30}).get('channels') or []
                for item in channels:
                    channel = item.get('id') or ''
                    if not channel or not allowed(channel):
                        continue
                    if not (item.get('is_im') or item.get('is_member') or allowed(channel, explicit=True)):
                        continue
                    try:
                        last = poll_state.get(channel)
                        if last is None and kind == 'schedule':
                            poll_state[channel] = str(time.time())
                            continue
                        last = last or '0'
                        messages = slack('conversations.history', {'channel': channel, 'limit': 30}).get('messages') or []
                        pending = []
                        for event in messages:
                            if float(event.get('ts') or 0) > float(last):
                                pending.append(event)
                            if event.get('reply_count') and float(event.get('latest_reply') or 0) > float(last):
                                replies = slack('conversations.replies', {'channel': channel, 'ts': event['ts'], 'oldest': last, 'limit': 30}).get('messages') or []
                                pending.extend(reply for reply in replies if float(reply.get('ts') or 0) > float(last) and reply.get('ts') != event['ts'])
                        pending.sort(key=lambda event: float(event.get('ts') or 0))
                        for event in pending:
                            event['channel'] = channel
                            if channel.startswith('D') or ('<@' + status['bot_user_id'] + '>') in (event.get('text') or ''):
                                respond(event)
                        timestamps = [event.get('ts') for event in pending if event.get('ts')]
                        if timestamps:
                            poll_state[channel] = max(timestamps, key=float)
                        elif channel not in poll_state:
                            poll_state[channel] = str(time.time())
                    except PollRateLimited as error:
                        poll_state['retry_at'] = error.retry_at
                        break
                    except (OSError, ValueError, RuntimeError) as error:
                        status['last_error'] = str(error)
                        writes['status'] = status
        except PollRateLimited as error:
            poll_state['retry_at'] = error.retry_at
        write_file('poll_state.json', poll_state)
print(json.dumps({'result': result, 'set_storage': writes}, ensure_ascii=False))

